DO $migration$ DECLARE signature text; definition text; BEGIN FOREACH signature IN ARRAY ARRAY['public.catalog_security_status()', 'public.enforce_catalog_security()'] LOOP SELECT pg_get_functiondef(signature::regprocedure) INTO definition; definition:=replace(definition,'scan.high_regression OR (scan.regression AND scan.high_count+scan.critical_count>0)','scan.high_regression'); EXECUTE definition; END LOOP; END; $migration$;